const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var geometry = ee.Geometry.Rectangle([-90.2, 29.0, -89.8, 29.3]); // Bay Dosgris region
  var start1985 = '1985-01-01';
  var end1985 = '1985-12-31';
  var start2024 = '2024-01-01';
  var end2024 = '2024-12-31';

  // Cloud masking function for Landsat 5
  function maskL5clouds(image) {
    var qa = image.select('QA_PIXEL');
    var cloud = qa.bitwiseAnd(1 << 3); // Cloud bit (3)
    var shadow = qa.bitwiseAnd(1 << 4); // Cloud shadow bit (4)
    var mask = cloud.or(shadow).not();
    return image.updateMask(mask);
  }

  // Cloud masking function for Landsat 8
  function maskL8clouds(image) {
    var qa = image.select('QA_PIXEL');
    var cloud = qa.bitwiseAnd(1 << 3);
    var shadow = qa.bitwiseAnd(1 << 4);
    var mask = cloud.or(shadow).not();
    return image.updateMask(mask);
  }

  // 2. Data Acquisition for 1985 (Landsat 5)
  var l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
            .filterBounds(geometry)
            .filterDate(start1985, end1985)
            .map(maskL5clouds);

  var l5size = l5.size().getInfo();
  if (l5size === 0) {
    // Try wider date range for 1985
    var l5_wider = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
                    .filterBounds(geometry)
                    .filterDate('1984-01-01', '1986-12-31')
                    .map(maskL5clouds);
    l5 = l5_wider;
    l5size = l5.size().getInfo();
    if (l5size === 0) {
      print("1985 Images: 0");
      print("<answer>C1</answer>");
      return;
    }
  }

  // 3. Data Acquisition for 2024 (Landsat 8)
  var l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
            .filterBounds(geometry)
            .filterDate(start2024, end2024)
            .map(maskL8clouds);

  var l8size = l8.size().getInfo();
  if (l8size === 0) {
    // Try Landsat 9 as fallback for 2024
    var l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
              .filterBounds(geometry)
              .filterDate(start2024, end2024)
              .map(maskL8clouds);
    l8 = l9;
    l8size = l8.size().getInfo();
    if (l8size === 0) {
      print("2024 Images: 0");
      print("<answer>C1</answer>");
      return;
    }
  }

  // Create median composites
  var comp1985 = l5.median().clip(geometry);
  var comp2024 = l8.median().clip(geometry);

  // Compute indices for 1985
  var mndwi1985 = comp1985.normalizedDifference(['SR_B2', 'SR_B5']).rename('mndwi'); // Green=SR_B2, SWIR1=SR_B5
  var ndvi1985 = comp1985.normalizedDifference(['SR_B4', 'SR_B3']).rename('ndvi'); // NIR=SR_B4, Red=SR_B3

  // Compute indices for 2024
  var mndwi2024 = comp2024.normalizedDifference(['SR_B3', 'SR_B6']).rename('mndwi'); // Green=SR_B3, SWIR1=SR_B6
  var ndvi2024 = comp2024.normalizedDifference(['SR_B5', 'SR_B4']).rename('ndvi'); // NIR=SR_B5, Red=SR_B4

  // Classification thresholds
  var water1985 = mndwi1985.gt(0.2).and(ndvi1985.lt(0.2)); // Open water
  var wetland1985 = mndwi1985.gt(0).and(ndvi1985.gt(0.2)); // Wetland

  var water2024 = mndwi2024.gt(0.2).and(ndvi2024.lt(0.2));
  var wetland2024 = mndwi2024.gt(0).and(ndvi2024.gt(0.2));

  // Count pixels for each class
  var waterCount1985 = water1985.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 300,
    maxPixels: 1e9
  }).get('mndwi');

  var wetlandCount1985 = wetland1985.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 300,
    maxPixels: 1e9
  }).get('mndwi');

  var waterCount2024 = water2024.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 300,
    maxPixels: 1e9
  }).get('mndwi');

  var wetlandCount2024 = wetland2024.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 300,
    maxPixels: 1e9
  }).get('mndwi');

  // Get the values
  var w1985 = waterCount1985.getInfo();
  var wl1985 = wetlandCount1985.getInfo();
  var w2024 = waterCount2024.getInfo();
  var wl2024 = wetlandCount2024.getInfo();

  // Check for valid pixels
  if (w1985 === 0 || wl1985 === 0 || w2024 === 0 || wl2024 === 0) {
    print("1985 Water Pixels: " + w1985 + ", Wetland Pixels: " + wl1985);
    print("2024 Water Pixels: " + w2024 + ", Wetland Pixels: " + wl2024);
    print("<answer>C2</answer>");
    return;
  }

  // Compute ratios
  var ratio1985 = w1985 / wl1985;
  var ratio2024 = w2024 / wl2024;

  // Validate ratios
  if (isNaN(ratio1985) || isNaN(ratio2024) || !isFinite(ratio1985) || !isFinite(ratio2024)) {
    print("1985 Ratio: " + ratio1985 + ", 2024 Ratio: " + ratio2024);
    print("<answer>C3</answer>");
    return;
  }

  // Print stats
  print("1985 Images: " + l5size + " (Water: " + w1985 + ", Wetland: " + wl1985 + ", Ratio: " + ratio1985.toFixed(3) + ")");
  print("2024 Images: " + l8size + " (Water: " + w2024 + ", Wetland: " + wl2024 + ", Ratio: " + ratio2024.toFixed(3) + ")");

  // Compare ratios
  if (ratio2024 > ratio1985) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

